bool checkColPairing(vector<pair<int,int>>& rowPairs, int midRow) {
    // For each column, compute its "signature" based on row pairs
    // Two columns can be paired if one's signature is the reverse of the other
    // For middle row, the two paired columns must have same char
    map<vector<pair<char,char>>, vector<int>> colGroups;
    for (int c = 0; c < W; c++) {
        vector<pair<char,char>> sig;
        for (auto& [r1,r2] : rowPairs) sig.push_back({grid[r1][c], grid[r2][c]});
        colGroups[sig].push_back(c);
    }
    // Each signature S must pair with reverse(S)
    // Check counts match
    set<vector<pair<char,char>>> visited;
    for (auto& [sig, cols] : colGroups) {
        if (visited.count(sig)) continue;
        vector<pair<char,char>> rsig;
        for (auto& [a,b] : sig) rsig.push_back({b,a});
        if (sig == rsig) {
            // self-paired, need even count (or odd if W is odd and middle col exists)
            // middle col: midRow char must match itself (always true)
            if (cols.size() % 2 != 0) { if (W % 2 == 0) return false; /* need exactly one middle */ }
        } else {
            if (!colGroups.count(rsig)) return false;
            if (colGroups[rsig].size() != cols.size()) return false;
            visited.insert(rsig);
        }
        visited.insert(sig);
    }
    if (W % 2 == 1) {
        // need exactly one self-paired column with odd count
        int oddSelf = 0;
        for (auto& [sig, cols] : colGroups) {
            vector<pair<char,char>> rsig;
            for (auto& [a,b] : sig) rsig.push_back({b,a});
            if (sig == rsig && cols.size() % 2 == 1) oddSelf += cols.size() % 2;
        }
        if (oddSelf != 1) return false;
    }
    return true;
}

