int check_cols(int row_p[]) {
    // For each column j, compute the column vector under row_p
    // Then check if columns can be paired such that col[a] = reverse(col[b])
    char cols[8][8];
    for (int j = 0; j < W; j++)
        for (int i = 0; i < H; i++)
            cols[j][i] = grid[row_p[i]][j];

    // Need to find permutation sigma of columns such that
    // cols[sigma(j)] = reverse(cols[sigma(W-1-j)])
    // i.e., pair columns into (W/2) pairs + possibly middle
    // Each pair (a,b): cols[a][i] = cols[b][H-1-i] for all i
    // If W odd, middle column must satisfy cols[m][i] = cols[m][H-1-i]

    // Build a graph: col a can pair with col b if they are reverses
    int can_pair[8][8];
    memset(can_pair, 0, sizeof(can_pair));
    for (int a = 0; a < W; a++)
        for (int b = 0; b < W; b++) {
            int ok = 1;
            for (int i = 0; i < H; i++)
                if (cols[a][i] != cols[b][H-1-i]) { ok = 0; break; }
            can_pair[a][b] = ok;
        }

    // If W is odd, there must be a column that is self-reverse
    // and we need to match the remaining W-1 columns into pairs
    // Use bitmask DP for matching
    int n = W;
    // dp[mask] = 1 if columns in mask can be perfectly matched into reverse pairs
    // For odd W, one column is "center" - try each self-reverse column as center

    if (n % 2 == 1) {
        // Try each column as center
        for (int c = 0; c < n; c++) {
            if (!can_pair[c][c]) continue;
            // Match remaining columns
            int full = (1 << n) - 1;
            int mask0 = full ^ (1 << c);
            // dp on mask0
            int dp[256];
            memset(dp, 0, sizeof(dp));
            dp[0] = 1;
            // iterate over submasks of mask0
            for (int m = 0; m <= mask0; m++) {
                if (!(m & mask0) == (m == (m & mask0))) {} // m must be subset of mask0
                if ((m & mask0) != m) continue;
                if (!dp[m]) continue;
                // find lowest unset bit in mask0 that's not in m
                int rem = mask0 ^ m;
                if (rem == 0) continue;
                int a = -1;
                for (int i = 0; i < n; i++) if (rem & (1<<i)) { a = i; break; }
                for (int b = 0; b < n; b++) {
                    if (b == a) continue;
                    if (!(rem & (1<<b))) continue;
                    if (can_pair[a][b]) {
                        dp[m | (1<<a) | (1<<b)] = 1;
                    }
                }
            }
            if (dp[mask0]) return 1;
        }
        return 0;
    } else {
        int full = (1 << n) - 1;
        int dp[256];
        memset(dp, 0, sizeof(dp));
        dp[0] = 1;
        for (int m = 0; m <= full; m++) {
            if (!dp[m]) continue;
            int rem = full ^ m;
            if (rem == 0) continue;
            int a = -1;
            for (int i = 0; i < n; i++) if (rem & (1<<i)) { a = i; break; }
            for (int b = 0; b < n; b++) {
                if (b == a) continue;
                if (!(rem & (1<<b))) continue;
                if (can_pair[a][b]) {
                    dp[m | (1<<a) | (1<<b)] = 1;
                }
            }
        }
        return dp[full];
    }
}

