        }
        return true;
    }

    static boolean isRowPalindrome(char[][] grid, int r, int W) {
        for (int j = 0; j < W / 2; j++) {
            if (grid[r][j] != grid[r][W - 1 - j]) return false;
        }
        return true;
    }

    static boolean colsEqual(char[][] grid, int c1, int c2, int H) {
        for (int i = 0; i < H; i++) {
            if (grid[i][c1] != grid[i][c2]) return false;
        }
        return true;
    }

    static boolean isColPalindrome(char[][] grid, int c, int H) {
        for (int i = 0; i < H / 2; i++) {
            if (grid[i][c] != grid[H - 1 - i][c]) return false;
        }
        return true;
    }
