import java.io.*;
import java.util.*;

public class Main {
    static int H, W;
    static char[][] a;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        H = fs.nextInt();
        W = fs.nextInt();
        a = new char[H][];
        for (int i = 0; i < H; i++) a[i] = fs.next().toCharArray();

        boolean ans;
        if (H <= W) {
            ans = solveByRows();
        } else {
            ans = solveByCols();
        }

        System.out.println(ans ? "YES" : "NO");
    }

    // Pair rows / choose one center row, then verify columns can be arranged.
    static boolean solveByRows() {
        boolean[] used = new boolean[H];
        return dfsRows(used, new int[H / 2][2], 0, -1);
    }

    static boolean dfsRows(boolean[] used, int[][] pairs, int pCnt, int centerRow) {
        int first = -1;
        for (int i = 0; i < H; i++) {
            if (!used[i]) {
                first = i;
                break;
            }
        }

        if (first == -1) {
            return checkColumnsGivenRows(pairs, pCnt, centerRow);
        }

        used[first] = true;

        // Put as center row if H is odd and center not chosen yet
        if ((H % 2 == 1) && centerRow == -1) {
            if (dfsRows(used, pairs, pCnt, first)) return true;
        }

        // Pair with another unused row
        for (int j = first + 1; j < H; j++) {
            if (!used[j]) {
                used[j] = true;
                pairs[pCnt][0] = first;
                pairs[pCnt][1] = j;
                if (dfsRows(used, pairs, pCnt + 1, centerRow)) return true;
                used[j] = false;
            }
        }

        used[first] = false;
        return false;
    }

    static boolean checkColumnsGivenRows(int[][] rowPairs, int pCnt, int centerRow) {
        // Build column signatures induced by row pairing.
        // Two columns x,y can be paired iff for every row pair (r1,r2):
        // a[r1][x]==a[r2][y] and a[r2][x]==a[r1][y]
        // and for center row c (if exists): a[c][x]==a[c][y]
        //
        // For each column, define:
        //   pair-part = sequence of ordered pairs (a[r1][col], a[r2][col]) over all row pairs
        //   center-part = a[c][col] if exists
        //
        // Then x can pair with y iff pair-part(y) is the "swapped" version of pair-part(x)
        // and center-part equal.
        HashMap<String, Integer> cnt = new HashMap<>();

        for (int col = 0; col < W; col++) {
            String key = buildColKey(col, rowPairs, pCnt, centerRow, false);
            cnt.put(key, cnt.getOrDefault(key, 0) + 1);
        }

        HashSet<String> seen = new HashSet<>();
        int oddSelf = 0;

        for (String key : cnt.keySet()) {
            if (seen.contains(key)) continue;
            String rev = reverseKey(key, pCnt, centerRow != -1);
            int c1 = cnt.getOrDefault(key, 0);
            int c2 = cnt.getOrDefault(rev, 0);
            seen.add(key);
            seen.add(rev);

            if (key.equals(rev)) {
                if ((c1 & 1) == 1) oddSelf++;
            } else {
                if (c1 != c2) return false;
            }
        }

        if ((W & 1) == 0) {
            return oddSelf == 0;
        } else {
            return oddSelf == 1;
        }
    }

    static String buildColKey(int col, int[][] rowPairs, int pCnt, int centerRow, boolean swapped) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pCnt; i++) {
            int r1 = rowPairs[i][0];
            int r2 = rowPairs[i][1];
            char c1 = a[r1][col], c2 = a[r2][col];
            if (!swapped) {
                sb.append(c1).append(c2).append('|');
            } else {
                sb.append(c2).append(c1).append('|');
            }
        }
        if (centerRow != -1) sb.append(a[centerRow][col]);
        return sb.toString();
    }

    static String reverseKey(String key, int pCnt, boolean hasCenter) {
        // Key format: for each pair, two chars + '|', then optional center char.
        StringBuilder sb = new StringBuilder();
        int idx = 0;
        for (int i = 0; i < pCnt; i++) {
            char c1 = key.charAt(idx);
            char c2 = key.charAt(idx + 1);
            sb.append(c2).append(c1).append('|');
            idx += 3;
        }
        if (hasCenter) sb.append(key.charAt(idx));
        return sb.toString();
    }

    // Symmetric alternative when H > W: pair columns first, then verify rows.
    static boolean solveByCols() {
        boolean[] used = new boolean[W];
        return dfsCols(used, new int[W / 2][2], 0, -1);
    }

    static boolean dfsCols(boolean[] used, int[][] pairs, int pCnt, int centerCol) {
        int first = -1;
        for (int i = 0; i < W; i++) {
            if (!used[i]) {
                first = i;
                break;
            }
        }

        if (first == -1) {
            return checkRowsGivenCols(pairs, pCnt, centerCol);
        }

        used[first] = true;

        if ((W % 2 == 1) && centerCol == -1) {
            if (dfsCols(used, pairs, pCnt, first)) return true;
        }

        for (int j = first + 1; j < W; j++) {
            if (!used[j]) {
                used[j] = true;
                pairs[pCnt][0] = first;
                pairs[pCnt][1] = j;
                if (dfsCols(used, pairs, pCnt + 1, centerCol)) return true;
                used[j] = false;
            }
        }

        used[first] = false;
        return false;
    }

    static boolean checkRowsGivenCols(int[][] colPairs, int pCnt, int centerCol) {
        HashMap<String, Integer> cnt = new HashMap<>();

        for (int row = 0; row < H; row++) {
            String key = buildRowKey(row, colPairs, pCnt, centerCol, false);
            cnt.put(key, cnt.getOrDefault(key, 0) + 1);
        }

        HashSet<String> seen = new HashSet<>();
        int oddSelf = 0;

        for (String key : cnt.keySet()) {
            if (seen.contains(key)) continue;
            String rev = reverseKey(key, pCnt, centerCol != -1);
            int c1 = cnt.getOrDefault(key, 0);
            int c2 = cnt.getOrDefault(rev, 0);
            seen.add(key);
            seen.add(rev);

            if (key.equals(rev)) {
                if ((c1 & 1) == 1) oddSelf++;
            } else {
                if (c1 != c2) return false;
            }
        }

        if ((H & 1) == 0) {
            return oddSelf == 0;
        } else {
            return oddSelf == 1;
        }
    }

    static String buildRowKey(int row, int[][] colPairs, int pCnt, int centerCol, boolean swapped) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < pCnt; i++) {
            int c1 = colPairs[i][0];
            int c2 = colPairs[i][1];
            char x = a[row][c1], y = a[row][c2];
            if (!swapped) {
                sb.append(x).append(y).append('|');
            } else {
                sb.append(y).append(x).append('|');
            }
        }
        if (centerCol != -1) sb.append(a[row][centerCol]);
        return sb.toString();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

from collections import Counter
import sys

def solve():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    grid = [list(input().strip()) for _ in range(H)]

    # We'll count letters in symmetric positions
    # For each pair (i, j) and (H-1-i, W-1-j), we collect letters
    counts = Counter()

    for i in range(H):
        for j in range(W):
            # Only consider each pair once
            if (i, j) <= ((H-1-i), (W-1-j)):
                counts[grid[i][j]] += 1
                if (i, j) != ((H-1-i), (W-1-j)):
                    counts[grid[H-1-i][W-1-j]] += 1

    # Now we need to form pairs of identical letters
    # Each symmetric position group must have even count (pairs) except possibly
    # the center if both H and W are odd.

    odd_count = 0
    for v in counts.values():
        if v % 2 == 1:
            odd_count += 1

    # The only allowed odd count is 1 if both H and W are odd (center cell)
    if H % 2 == 1 and W % 2 == 1:
        if odd_count == 1:
            print("YES")
        else:
            print("NO")
    elif H % 2 == 1 or W % 2 == 1:
        # One dimension odd means middle row or column: odd is allowed if it pairs within that line
        # Actually each symmetric pair has size 2 except middle row/col pairs that are size 1.
        # The middle line pairs are already counted; they must form pairs among themselves.
        # In these cases, odd_count must be 0 because the middle has an even number of cells
        # when paired along the other axis.
        if odd_count == 0:
            print("YES")
        else:
            print("NO")
    else:
        # Both even: all must be even
        if odd_count == 0:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
